17		"github.com/go-git/go-git/v6/plumbing/filemode"
18		"github.com/go-git/go-git/v6/plumbing/object"
19	)
20	
21	// TreeChange represents a single file change within a tree.
22	// Use a nil Entry to indicate deletion.
23	type TreeChange struct {
24		// Path is the full path within the tree (e.g., "src/pkg/handler.go").
25		Path string
26		// Entry is the new tree entry. Nil means delete the file at Path.
27		Entry *object.TreeEntry
28	}
29	
30	// MergeMode controls how entries at the leaf directory are handled by UpdateSubtree.
31	type MergeMode int
32	
33	const (
34		// ReplaceAll replaces the entire leaf directory contents with the new entries.
35		ReplaceAll MergeMode = iota
36		// MergeKeepExisting merges new entries into the existing leaf directory,
37		// keeping existing entries that are not overwritten (unless in DeleteNames).
38		MergeKeepExisting
39	)
40	
41	// UpdateSubtreeOptions configures the behavior of UpdateSubtree.
42	type UpdateSubtreeOptions struct {
43		// MergeMode controls how entries at the leaf directory are handled.
44		MergeMode MergeMode
45		// DeleteNames lists entry names (at the leaf directory level) to delete.
46		// Only applicable when MergeMode is MergeKeepExisting.
47		DeleteNames []string
48	}
49	
50	// UpdateSubtree replaces or creates a subtree at the given path within an existing tree.
51	// It walks the tree path, replacing only the entries along the modified path.
52	// All sibling entries at each level retain their original hashes — no re-reading needed.
53	//
54	// pathSegments is the directory path split into segments (e.g., ["a3", "b2c4d5e6f7"]).
55	// newEntries are the files/dirs to place at the leaf directory.
56	// Returns the new root tree hash.
57	func UpdateSubtree(
58		repo *git.Repository,
59		rootTreeHash plumbing.Hash,
60		pathSegments []string,
61		newEntries []object.TreeEntry,
62		opts UpdateSubtreeOptions,
63	) (plumbing.Hash, error) {
64		if len(pathSegments) == 0 {
65			return buildLeafTree(repo, rootTreeHash, newEntries, opts)
66		}
67	
68		// Read the current tree at this level
69		// Get all entries in the tree and add them to the currentEntries slice
70		var currentEntries []object.TreeEntry
71		if rootTreeHash != plumbing.ZeroHash {
72			tree, err := repo.TreeObject(rootTreeHash)
73			if err != nil {
74				return plumbing.ZeroHash, fmt.Errorf("failed to read tree %s: %w", rootTreeHash, err)
75			}
76			currentEntries = tree.Entries
77		}
78	
79		targetDir := pathSegments[0]
80		remainingPath := pathSegments[1:]
81	
82		// Find the existing subtree entry for targetDir
83		var existingSubtreeHash plumbing.Hash
84		found := false
85		for _, entry := range currentEntries {
86			if entry.Name == targetDir && entry.Mode == filemode.Dir {
87				existingSubtreeHash = entry.Hash
88				found = true
89				break
90			}
91		}
92	
93		// Recurse into the subtree
94		newSubtreeHash, err := UpdateSubtree(repo, existingSubtreeHash, remainingPath, newEntries, opts)
95		if err != nil {
96			return plumbing.ZeroHash, err
97		}
98	
99		// Build a new tree at this level with the updated subtree entry
100		updatedEntries := make([]object.TreeEntry, 0, len(currentEntries)+1)
101		replaced := false
102		for _, entry := range currentEntries {
103			if entry.Name == targetDir {
104				updatedEntries = append(updatedEntries, object.TreeEntry{
105					Name: targetDir,
106					Mode: filemode.Dir,
107					Hash: newSubtreeHash,
108				})
109				replaced = true
110			} else {
111				updatedEntries = append(updatedEntries, entry)
112			}
113		}
114		if !found && !replaced {
115			updatedEntries = append(updatedEntries, object.TreeEntry{
116				Name: targetDir,
117				Mode: filemode.Dir,
118				Hash: newSubtreeHash,
119			})
120		}
121	
122		sortTreeEntries(updatedEntries)
123		return storeTree(repo, updatedEntries)
124	}
125	
126	// buildLeafTree builds the tree at the leaf of the UpdateSubtree path.
127	func buildLeafTree(
128		repo *git.Repository,
129		existingTreeHash plumbing.Hash,
130		newEntries []object.TreeEntry,
131		opts UpdateSubtreeOptions,
132	) (plumbing.Hash, error) {
133		if opts.MergeMode == ReplaceAll || existingTreeHash == plumbing.ZeroHash {
134			sorted := make([]object.TreeEntry, len(newEntries))
135			copy(sorted, newEntries)
136			sortTreeEntries(sorted)
137			return storeTree(repo, sorted)
138		}
139	
140		// MergeKeepExisting: read existing tree, merge
141		existingTree, err := repo.TreeObject(existingTreeHash)
142		if err != nil {
143			sorted := make([]object.TreeEntry, len(newEntries))
144			copy(sorted, newEntries)
145			sortTreeEntries(sorted)
146			return storeTree(repo, sorted)
147		}
148	
149		// Build lookup of new entries by name
150		newByName := make(map[string]object.TreeEntry, len(newEntries))
151		for _, e := range newEntries {
152			newByName[e.Name] = e
153		}
154	
155		// Build delete set
156		deleteSet := make(map[string]bool, len(opts.DeleteNames))
157		for _, name := range opts.DeleteNames {
158			deleteSet[name] = true
159		}
160	
161		// Merge: keep existing unless overwritten or deleted
162		merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
163		for _, existing := range existingTree.Entries {
164			if deleteSet[existing.Name] {
165				continue
166			}
167			if replacement, ok := newByName[existing.Name]; ok {
168				merged = append(merged, replacement)
169				delete(newByName, existing.Name)
170			} else {
171				merged = append(merged, existing)
172			}
173		}
174		// Add remaining new entries (ones that didn't replace an existing entry)
175		for _, e := range newEntries {
176			if _, stillNew := newByName[e.Name]; stillNew {
177				merged = append(merged, e)
178			}
179		}
180	
181		sortTreeEntries(merged)
182		return storeTree(repo, merged)
183	}
184	
185	// storeTree creates a git tree object from entries and stores it in the repo.
186	func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
187		tree := &object.Tree{Entries: entries}
188		obj := repo.Storer.NewEncodedObject()
189		if err := tree.Encode(obj); err != nil {
190			return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
191		}
192		hash, err := repo.Storer.SetEncodedObject(obj)
193		if err != nil {
194			return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
195		}
196		return hash, nil
197	}
198	
199	// ApplyTreeChanges applies multiple file-level changes to a tree efficiently.
200	// Changes are grouped by directory and applied in a single recursive pass.
201	// Unchanged subdirectories retain their hashes — this is the key optimization
202	// over FlattenTree + BuildTreeFromEntries for sparse changes.
203	func ApplyTreeChanges(
204		ctx context.Context,
205		repo *git.Repository,
206		rootTreeHash plumbing.Hash,
207		changes []TreeChange,
208	) (plumbing.Hash, error) {
209		if len(changes) == 0 {
210			return rootTreeHash, nil
211		}
212	
213		var currentEntries []object.TreeEntry
214		if rootTreeHash != plumbing.ZeroHash {
215			tree, err := repo.TreeObject(rootTreeHash)
216			if err != nil {
217				cliEntries, cliErr := readTreeEntriesViaCLI(ctx, rootTreeHash)
218				if cliErr != nil {
219					return plumbing.ZeroHash, fmt.Errorf("failed to read tree: %w", errors.Join(err, cliErr))
220				}
221				logging.Warn(ctx, "ApplyTreeChanges: go-git tree read failed, used git ls-tree fallback",
222					slog.String("tree", rootTreeHash.String()[:12]),
223					slog.String("gogit_error", err.Error()),
224				)
225				currentEntries = cliEntries
226			} else {
227				currentEntries = make([]object.TreeEntry, len(tree.Entries))
228				copy(currentEntries, tree.Entries)
229			}
230		}
231	
232		// Group changes by first path segment
233		type dirChanges struct {
234			subChanges []TreeChange // Changes within this subdirectory
235			fileChange *TreeChange  // Direct file change at this level (nil if none)
236		}
237		grouped := make(map[string]*dirChanges)
238	
239		for i := range changes {
240			c := changes[i]
241			normalizedPath, err := normalizeGitTreePath(c.Path)
242			if err != nil {
243				logInvalidGitTreePath(ctx, "apply tree change", c.Path, err)
244				continue
245			}
246	
247			first, rest := splitFirstSegment(normalizedPath)
248			if grouped[first] == nil {
249				grouped[first] = &dirChanges{}
250			}
251			if rest == "" {
252				cc := c
253				cc.Path = normalizedPath
254				grouped[first].fileChange = &cc
255			} else {
256				grouped[first].subChanges = append(grouped[first].subChanges, TreeChange{
257					Path:  rest,
258					Entry: c.Entry,
259				})
260			}
261		}
262	
263		// Build entry map for modifications
264		entryMap := make(map[string]object.TreeEntry, len(currentEntries))
265		for _, e := range currentEntries {
266			entryMap[e.Name] = e
267		}
268	
269		// Process each group
270		for name, dc := range grouped {
271			if dc.fileChange != nil {
272				if dc.fileChange.Entry == nil {
273					delete(entryMap, name)
274				} else {
275					entryMap[name] = object.TreeEntry{
276						Name: name,
277						Mode: dc.fileChange.Entry.Mode,
278						Hash: dc.fileChange.Entry.Hash,
279					}
280				}
281			}
282			if len(dc.subChanges) > 0 {
283				existingHash := plumbing.ZeroHash
284				if existing, ok := entryMap[name]; ok && existing.Mode == filemode.Dir {
285					existingHash = existing.Hash
286				}
287				newSubHash, err := ApplyTreeChanges(ctx, repo, existingHash, dc.subChanges)
288				if err != nil {
289					return plumbing.ZeroHash, fmt.Errorf("failed to apply changes in %s: %w", name, err)
290				}
291				entryMap[name] = object.TreeEntry{
292					Name: name,
293					Mode: filemode.Dir,
294					Hash: newSubHash,
295				}
296			}
297		}
298	
299		result := make([]object.TreeEntry, 0, len(entryMap))
300		for _, e := range entryMap {
301			result = append(result, e)
302		}
303		sortTreeEntries(result)
304		return storeTree(repo, result)
305	}
306	
307	// readTreeEntriesViaCLI parses `git ls-tree <hash>` into go-git TreeEntry
308	// values. Fallback for go-git tree reads that fail in partial-clone repos
309	// where the storer's packfile index has gone stale — analogous to the
310	// blob-side workaround in FetchingTree.blobOnDisk.
311	func readTreeEntriesViaCLI(ctx context.Context, hash plumbing.Hash) ([]object.TreeEntry, error) {
312		short := hash.String()[:12]
313		cmd := exec.CommandContext(ctx, "git", "ls-tree", hash.String())
314		output, err := cmd.Output()
315		if err != nil {
316			return nil, fmt.Errorf("git ls-tree %s: %w", short, err)
317		}
318		trimmed := strings.TrimRight(string(output), "\n")
319		if trimmed == "" {
320			return nil, nil
321		}
322		lines := strings.Split(trimmed, "\n")
323		entries := make([]object.TreeEntry, 0, len(lines))
324		for _, line := range lines {
325			// Format: "<mode> <type> <hash>\t<name>"
326			tab := strings.IndexByte(line, '\t')
327			if tab < 0 {
328				return nil, fmt.Errorf("git ls-tree %s: malformed line %q", short, line)
329			}
330			name := line[tab+1:]
331			fields := strings.Fields(line[:tab])
332			if len(fields) != 3 {
333				return nil, fmt.Errorf("git ls-tree %s: malformed entry %q", short, line)
334			}
335			mode, modeErr := filemode.New(fields[0])
336			if modeErr != nil {
337				return nil, fmt.Errorf("git ls-tree %s: invalid mode %q: %w", short, fields[0], modeErr)
338			}
339			entries = append(entries, object.TreeEntry{
340				Name: name,
341				Mode: mode,
342				Hash: plumbing.NewHash(fields[2]),
343			})
344		}
345		return entries, nil
346	}
347	
348	// WalkCheckpointShards iterates over the two-level shard structure (<id[:2]>/<id[2:]>/)
349	// in a checkpoint tree, calling fn for each checkpoint found. It skips non-directory
350	// and non-shard entries at both levels, such as legacy generation.json files or
351	// other metadata kept outside shard directories. The callback receives the parsed
352	// checkpoint ID and the tree hash of the checkpoint subtree.
353	func WalkCheckpointShards(ctx context.Context, repo *git.Repository, tree *object.Tree, fn func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error) error {
354		for _, bucketEntry := range tree.Entries {
355			if err := ctx.Err(); err != nil {
356				return err //nolint:wrapcheck // propagate context cancellation unwrapped
357			}
358			if bucketEntry.Mode != filemode.Dir {
359				continue
360			}
361			if len(bucketEntry.Name) != 2 {
362				continue
363			}
364	
365			bucketTree, err := repo.TreeObject(bucketEntry.Hash)
366			if err != nil {
367				continue
368			}
369	
370			if err := ctx.Err(); err != nil {
371				return err //nolint:wrapcheck // propagate context cancellation unwrapped
372			}
373			for _, cpEntry := range bucketTree.Entries {
374				if cpEntry.Mode != filemode.Dir {
375					continue
376				}
377	
378				cpID, err := id.NewCheckpointID(bucketEntry.Name + cpEntry.Name)
379				if err != nil {
380					continue
381				}
382	
383				if err := fn(cpID, cpEntry.Hash); err != nil {
384					return err
385				}
386			}
387		}
388		return nil
389	}
390	
391	func normalizeGitTreePath(path string) (string, error) {
392		if path == "" {
393			return "", errors.New("path is empty")
394		}
395	
396		path = filepath.ToSlash(path)
397		if isAbsoluteGitTreePath(path) {
398			return "", errors.New("path must be relative")
399		}
400	
401		parts := strings.Split(path, "/")
402		for _, part := range parts {
403			if part == "" {
404				return "", errors.New("path contains empty segment")
405			}
406			if part == "." || part == ".." {
407				return "", fmt.Errorf("path contains invalid segment %q", part)
408			}
409		}
410	
411		return path, nil
412	}
413	
414	func isAbsoluteGitTreePath(path string) bool {
415		if filepath.IsAbs(path) {
416			return true
417		}
418	
419		if len(path) >= 3 && path[1] == ':' && path[2] == '/' {
420			drive := path[0]
421			return (drive >= 'a' && drive <= 'z') || (drive >= 'A' && drive <= 'Z')
422		}
423	
424		return false
425	}
426	
427	func logInvalidGitTreePath(ctx context.Context, operation, path string, err error) {
428		logging.Warn(ctx, "skipping invalid git tree path",
429			slog.String("operation", operation),
430			slog.String("path", path),
431			slog.String("error", err.Error()),
432		)
433	}
434	
435	// splitFirstSegment splits "a/b/c" into ("a", "b/c"), and "file.txt" into ("file.txt", "").
436	func splitFirstSegment(path string) (first, rest string) {
437		parts := strings.SplitN(path, "/", 2)
438		if len(parts) == 1 {
439			return parts[0], ""
440		}
441		return parts[0], parts[1]
442	}
443	
444	// getSessionsBranchRef returns the primary metadata ref's commit hash and root tree
445	// hash without flattening the tree.
446	func (s *GitStore) getSessionsBranchRef() (plumbing.Hash, plumbing.Hash, error) {
447		ref, err := s.repo.Reference(s.refs.Primary, true)
448		if err != nil {
449			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get primary metadata ref %s: %w", s.refs.Primary, err)
450		}
451	
452		parentCommit, err := s.repo.CommitObject(ref.Hash())
453		if err != nil {
454			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
455		}
456	
457		return ref.Hash(), parentCommit.TreeHash, nil
458	}
