1	// Package fsstore is a reference, test-only persistent checkpoint backend that
2	// stores checkpoints as JSON files on disk. It exists to exercise the pluggable
3	// backend seam (registry + mirror fan-out) with a real, non-git implementation
4	// of the api/checkpoint contract, and to serve as a worked example for new
5	// backends.
6	//
7	// It is deliberately NOT registered by production code: only RegisterForTesting
8	// wires it into the checkpoint registry, so a production binary can never select
9	// it. As a mirror it receives best-effort write fan-out; it intentionally ignores
10	// the git-specific blob-hash fields of the contract and stores transcript bytes
11	// directly, which keeps the example small and makes the contract's remaining
12	// git leakage concrete.
13	//
14	// It is faithful to the contract's per-session metadata and write-request
15	// semantics — including prompt and summary redaction via the shared
16	// checkpoint helpers — but it does not replicate two git-writer behaviors:
17	// cross-session aggregation (the root summary's TokenUsage reflects the latest
18	// session, not a sum) and derived stamps the git writer adds (CLI version,
19	// skill-events version). Neither is needed to validate the pluggable seam.
20	package fsstore
21	
22	import (
23		"context"
24		"encoding/json"
25		"fmt"
26		"os"
27		"path/filepath"
28		"sort"
29		"strings"
30		"sync"
31		"time"
32	
33		cp "github.com/entireio/cli/api/checkpoint"
34		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
35		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
36		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
37	)
38	
39	// BackendType is the registry type name for the filesystem reference backend.
40	const BackendType = "fs"
41	
42	// Store is a JSON-file-backed persistent checkpoint store. One file per
43	// checkpoint (<root>/<checkpoint-id>.json) holds the root summary plus all
44	// session content.
45	type Store struct {
46		root string
47		mu   sync.Mutex
48	}
49	
50	// New constructs a filesystem store rooted at dir.
51	func New(dir string) *Store {
52		return &Store{root: dir}
53	}
54	
55	type storedSession struct {
56		SessionID  string      `json:"session_id"`
57		Metadata   cp.Metadata `json:"metadata"`
58		Transcript []byte      `json:"transcript,omitempty"`
59		Prompts    string      `json:"prompts,omitempty"`
60	}
61	
62	type storedCheckpoint struct {
63		Summary  cp.CheckpointSummary `json:"summary"`
64		Sessions []storedSession      `json:"sessions"`
65	}
66	
67	var (
68		_ cp.PersistentStore = (*Store)(nil)
69		_ cp.Writer          = (*Store)(nil)
70	)
71	
72	func (s *Store) path(checkpointID id.CheckpointID) string {
73		return filepath.Join(s.root, string(checkpointID)+".json")
74	}
75	
76	// load reads the stored checkpoint, returning (nil, nil) when it does not exist.
77	func (s *Store) load(checkpointID id.CheckpointID) (*storedCheckpoint, error) {
78		data, err := os.ReadFile(s.path(checkpointID))
79		if err != nil {
80			if os.IsNotExist(err) {
81				return nil, nil //nolint:nilnil // absent checkpoint, not an error
82			}
83			return nil, fmt.Errorf("fsstore: read %s: %w", checkpointID, err)
84		}
85		var sc storedCheckpoint
86		if err := json.Unmarshal(data, &sc); err != nil {
87			return nil, fmt.Errorf("fsstore: parse %s: %w", checkpointID, err)
88		}
89		return &sc, nil
90	}
91	
92	func (s *Store) save(sc *storedCheckpoint) error {
93		if err := os.MkdirAll(s.root, 0o750); err != nil {
94			return fmt.Errorf("fsstore: create root %s: %w", s.root, err)
95		}
96		data, err := json.MarshalIndent(sc, "", "  ")
97		if err != nil {
98			return fmt.Errorf("fsstore: encode %s: %w", sc.Summary.CheckpointID, err)
99		}
100		// Write atomically via the shared helper (unique temp file, cleaned up on
101		// failure) so a reader never observes a partial document. This guards a
102		// single writer's in-progress write; cross-process concurrency is out of
103		// scope for this test-only backend.
104		if err := jsonutil.WriteFileAtomic(s.path(sc.Summary.CheckpointID), data, 0o600); err != nil {
105			return fmt.Errorf("fsstore: write %s: %w", sc.Summary.CheckpointID, err)
106		}
107		return nil
108	}
109	
110	// Write dispatches on the request type, mirroring the git store's Write.
111	func (s *Store) Write(_ context.Context, req cp.WriteRequest) error {
112		s.mu.Lock()
113		defer s.mu.Unlock()
114	
115		switch r := req.(type) {
116		case cp.Session:
117			return s.writeSession(cp.WriteOptions(r))
118		case cp.SessionTranscript:
119			return s.backfillTranscript(cp.UpdateOptions(r))
120		case cp.SessionSummary:
121			return s.writeSessionSummary(r)
122		case cp.CheckpointAttribution:
123			return s.writeAttribution(r)
124		default:
125			return fmt.Errorf("fsstore: unsupported write request %T", req)
126		}
127	}
128	
129	func (s *Store) writeSession(opts cp.WriteOptions) error {
130		sc, err := s.load(opts.CheckpointID)
131		if err != nil {
132			return err
133		}
134		if sc == nil {
135			sc = &storedCheckpoint{Summary: cp.CheckpointSummary{CheckpointID: opts.CheckpointID}}
136		}
137	
138		session := storedSession{
139			SessionID:  opts.SessionID,
140			Metadata:   metadataFromWriteOptions(opts),
141			Transcript: opts.Transcript.Bytes(),
142			Prompts:    checkpoint.RedactedJoinedPrompts(opts.Prompts),
143		}
144		sc.Sessions = upsertSession(sc.Sessions, session)
145	
146		// Summary-level flags accumulate across sessions and survive recompute.
147		sc.Summary.HasReview = sc.Summary.HasReview || opts.HasReview
148		sc.Summary.HasInvestigation = sc.Summary.HasInvestigation || opts.HasInvestigation
149		if opts.CombinedAttribution != nil {
150			// Migration path: an initial write may carry holistic attribution. Normal
151			// condensation sets this later via a CheckpointAttribution write instead.
152			sc.Summary.CombinedAttribution = opts.CombinedAttribution
153		}
154	
155		recomputeSummary(sc)
156		return s.save(sc)
157	}
