159	func (s *Store) backfillTranscript(opts cp.UpdateOptions) error {
160		sc, err := s.load(opts.CheckpointID)
161		if err != nil {
162			return err
163		}
164		if sc == nil {
165			return fmt.Errorf("fsstore: cannot backfill transcript for unknown checkpoint %s", opts.CheckpointID)
166		}
167		idx := sessionIndexByID(sc.Sessions, opts.SessionID)
168		if idx < 0 {
169			return fmt.Errorf("fsstore: cannot backfill transcript for unknown session %q in %s", opts.SessionID, opts.CheckpointID)
170		}
171		// Replace semantics, but do not clobber sibling fields (matches the git
172		// store's stop-time transcript backfill).
173		sc.Sessions[idx].Transcript = opts.Transcript.Bytes()
174		sc.Sessions[idx].Prompts = checkpoint.RedactedJoinedPrompts(opts.Prompts)
175		if len(opts.SkillEvents) > 0 {
176			sc.Sessions[idx].Metadata.SkillEvents = opts.SkillEvents
177		}
178		return s.save(sc)
179	}
