218	func (s *Store) List(_ context.Context) ([]cp.CheckpointInfo, error) {
219		s.mu.Lock()
220		defer s.mu.Unlock()
221	
222		entries, err := os.ReadDir(s.root)
223		if err != nil {
224			if os.IsNotExist(err) {
225				return nil, nil
226			}
227			return nil, fmt.Errorf("fsstore: list %s: %w", s.root, err)
228		}
229	
230		var infos []cp.CheckpointInfo
231		for _, e := range entries {
232			if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
233				continue
234			}
235			checkpointID := id.CheckpointID(strings.TrimSuffix(e.Name(), ".json"))
236			sc, err := s.load(checkpointID)
237			if err != nil {
238				return nil, err
239			}
240			if sc == nil {
241				continue
242			}
243			infos = append(infos, infoFromStored(sc))
244		}
245		sort.Slice(infos, func(i, j int) bool { return infos[i].CreatedAt.After(infos[j].CreatedAt) })
246		return infos, nil
247	}
