346	func upsertSession(sessions []storedSession, session storedSession) []storedSession {
347		if idx := sessionIndexByID(sessions, session.SessionID); idx >= 0 {
348			sessions[idx] = session
349			return sessions
350		}
351		return append(sessions, session)
352	}
