363	// recomputeSummary rebuilds the aggregated root summary from the sessions, so a
364	// reader sees one Sessions entry per stored session and aggregate counts.
365	func recomputeSummary(sc *storedCheckpoint) {
366		summary := &sc.Summary
367		summary.Sessions = make([]cp.SessionFilePaths, len(sc.Sessions))
368		summary.CheckpointsCount = 0
369		files := map[string]struct{}{}
370		var orderedFiles []string
371	
372		for i := range sc.Sessions {
373			session := &sc.Sessions[i]
374			summary.Sessions[i] = cp.SessionFilePaths{
375				Metadata:   fmt.Sprintf("%d/metadata.json", i+1),
376				Transcript: fmt.Sprintf("%d/full.jsonl", i+1),
377				Prompt:     fmt.Sprintf("%d/prompt.txt", i+1),
378			}
379			summary.CheckpointsCount += session.Metadata.CheckpointsCount
380			if session.Metadata.Strategy != "" {
381				summary.Strategy = session.Metadata.Strategy
382			}
383			if session.Metadata.Branch != "" {
384				summary.Branch = session.Metadata.Branch
385			}
386			if session.Metadata.TokenUsage != nil {
387				summary.TokenUsage = session.Metadata.TokenUsage
388			}
389			for _, f := range session.Metadata.FilesTouched {
390				if _, seen := files[f]; !seen {
391					files[f] = struct{}{}
392					orderedFiles = append(orderedFiles, f)
393				}
394			}
395		}
396		summary.FilesTouched = orderedFiles
397	}
398	
399	func infoFromStored(sc *storedCheckpoint) cp.CheckpointInfo {
400		info := cp.CheckpointInfo{
401			CheckpointID:     sc.Summary.CheckpointID,
402			CheckpointsCount: sc.Summary.CheckpointsCount,
403			FilesTouched:     sc.Summary.FilesTouched,
404			SessionCount:     len(sc.Sessions),
405		}
406		if n := len(sc.Sessions); n > 0 {
407			last := sc.Sessions[n-1]
408			info.SessionID = last.SessionID
409			info.CreatedAt = last.Metadata.CreatedAt
410			info.Agent = last.Metadata.Agent
411			info.IsTask = last.Metadata.IsTask
412			info.ToolUseID = last.Metadata.ToolUseID
413		}
414		info.SessionIDs = make([]string, 0, len(sc.Sessions))
415		for i := range sc.Sessions {
416			info.SessionIDs = append(info.SessionIDs, sc.Sessions[i].SessionID)
417		}
418		return info
419	}
